"use strict";
// patch-regen-rows.js
// Backfills missing metadata fields on rows regenerated by regenerate-dirty-rows.js.
// Regenerated rows have all content fields but are missing structural fields
// (processId, scopeItemId, scopeItemName, status, module, ragStatus, etc.)
// that the UI and Excel builder expect.
//
// Run: node patch-regen-rows.js

const fs   = require("fs");
const path = require("path");
const { LOB_MODULE } = require("./agents/shared");

const CACHE_PATH = path.join(__dirname, "kdd-cache.json");
const cache = JSON.parse(fs.readFileSync(CACHE_PATH, "utf8"));

// Fields that must exist on every row — copied from a sibling row in the same scope item
const STRUCT_FIELDS = [
  "processId", "scopeItemId", "scopeItemName",
  "status", "source", "dataSource", "module",
  "l3", "l4", "decisionMade", "sapConsultant",
  "ragStatus", "configEffort", "integrationFlags"
];

let patched = 0;
let skipped = 0;

for (const [id, cacheItem] of Object.entries(cache.items)) {
  const rows = cacheItem.rows || [];
  if (!rows.length) continue;

  // Find a reference row (not a regenerated one) to copy structural fields from
  const refRow = rows.find(r => r.processId && !r.needsRegeneration &&
                                !r.kddId?.includes("KDD-004") &&
                                !r.kddId?.includes("KDD-012"));
  if (!refRow) { skipped++; continue; }

  const module = LOB_MODULE[refRow.l1] || LOB_MODULE[cacheItem.lob] || "GEN";

  for (const row of rows) {
    // A row needs patching if it's missing processId (key structural field)
    if (row.processId) continue;

    const kddSuffix = (row.kddId || "").split("-").pop(); // e.g. "KDD-004"

    // Determine l3/l4 based on which KDD type this is
    let l3, l4, configEffort;
    if (kddSuffix === "KDD-004") {
      l3          = "Fiori Configuration";
      l4          = "Configuration App";
      configEffort = "Minimal (<1 day)";
    } else if (kddSuffix === "KDD-012") {
      l3          = "Data Migration";
      l4          = "Migration Cockpit";
      configEffort = "Medium (1-3 days)";
    } else {
      l3          = refRow.l3 || "";
      l4          = refRow.l4 || "";
      configEffort = refRow.configEffort || "";
    }

    // Backfill all missing structural fields
    row.processId      = row.kddId;                          // same as kddId
    row.scopeItemId    = id;
    row.scopeItemName  = refRow.scopeItemName || row.l2 || "";
    row.status         = "Open";
    row.source         = "Fulcrum AI";                       // marks as AI-regenerated
    row.dataSource     = "claude";
    row.module         = module;
    row.l3             = l3;
    row.l4             = l4;
    row.decisionMade   = "";
    row.sapConsultant  = "";
    row.ragStatus      = "Green";
    row.configEffort   = configEffort;
    row.integrationFlags = "";

    // Remove the helper flag — row is now fully clean
    delete row.needsRegeneration;

    patched++;
  }
}

fs.writeFileSync(CACHE_PATH, JSON.stringify(cache, null, 2), "utf8");

console.log("\n╔══════════════════════════════════════════════╗");
console.log("║      REGEN ROW PATCH COMPLETE                ║");
console.log("╚══════════════════════════════════════════════╝\n");
console.log("Rows patched:  " + patched);
console.log("Items skipped: " + skipped + " (no ref row found)");
console.log("Cache saved.\n");

// Quick verify
const sample = Object.values(cache.items)[10];
const sampleRow = (sample.rows||[]).find(r=>r.kddId?.includes("KDD-004"));
if (sampleRow) {
  const missing = STRUCT_FIELDS.filter(f => sampleRow[f] === undefined);
  console.log(missing.length === 0
    ? "✅ Spot-check passed — all structural fields present on KDD-004 row."
    : "⚠️  Still missing: " + missing.join(", "));
}
